<?php namespace App\Controllers; class Users extends BaseController{public function index(){if($r=$this->mustAdmin())return $r;$rows=(new \App\Models\UserModel())->orderBy('id','DESC')->findAll();return $this->render('users/index',['pageTitle'=>'Users','rows'=>$rows]);}public function create(){if($r=$this->mustAdmin())return $r;$p=$this->request->getPost();$p['password_hash']=password_hash($p['password'],PASSWORD_DEFAULT);unset($p['password']);(new \App\Models\UserModel())->insert($p);return redirect()->back()->with('success','User created.');}public function toggle($id){if($r=$this->mustAdmin())return $r;$m=new \App\Models\UserModel();$u=$m->find($id);if($u&&$u['id']!=session()->get('user')['id'])$m->update($id,['is_active'=>$u['is_active']?0:1]);return redirect()->back();}}